== assets prepare ==
import { cp, mkdir, rm } from 'node:fs/promises';
import { resolve } from 'node:path';

const repositoryRoot = resolve(import.meta.dirname, '..');
const source = resolve(repositoryRoot, 'third_party/galbot_one_golf_description/mjcf');
const destination = resolve(repositoryRoot, 'apps/web/public/assets/robots/galbot-one-golf');

await rm(destination, { recursive: true, force: true });
await mkdir(destination, { recursive: true });
await cp(source, destination, { recursive: true });

console.log(`Prepared Galbot MJCF browser assets at ${destination}`);

